import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { Row, Icon, Button, Tag, Table, Select } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import { LayoutContentWrapper } from '../../../components/utility/layoutWrapper.style'
import claimActions from '../../redux/claims/actions'
import { connect } from 'react-redux'
import QueryString from 'query-string'
import { FilterInput } from '../../../components/tables/helperCells'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import UserActions from '../../redux/user/actions'
import policyActions from '../../../redux/policy/actions'
const {
  listticketData
} = claimActions
const { getInternalUsers } = UserActions
const { getProducts } = policyActions

const { Option } = Select

class Notifications extends Component {
  constructor (props) {
    super(props)
    this.state = {
      listticketData: [],
      searchText: '',
      pagination: {},
      loading: false,
      metaData: {},
      totalRecords: '',
      searchTextQuery: {},
      filteredInfo: {},
      notificationsFilter: {},
      products: []

    }
  }
  componentWillReceiveProps (nextProps) {
    const {
      data: tabledata } = nextProps
    if (tabledata !== undefined) {
      this.setState({
        listticketData: tabledata.listticketData.data,
        metaData: tabledata.listticketData.meta_data
      }, () => {
        this.setState({
          totalRecords: this.state.metaData && this.state.metaData['total_records']
        })
      })
      let productArray = []
      if (!!tabledata.listticketData && !!tabledata.listticketData.data) {
        tabledata.listticketData.data.forEach(item => {
          productArray.push(item.product_key)
        })
      }
      productArray = [...new Set(productArray)]
      this.setState({
        products: productArray
      })
    }
  }
  componentDidMount () {
    // const {history, location} = this.props
    // const querySearch = QueryString.parse(location.search)
    this.fetch()
    this.props.getProducts()
    this.props.getInternalUsers()

    // this.props.getClaimFilters()
  }
  detailPage = id => {
    const { history } = this.props
    history.push(`/claims/${id}`)
  };

  getColumnSearchProps = dataIndex => {
    const { products } = this.props
    const { searchTextQuery, isChange } = this.state
    const querySearch = QueryString.parse(this.props.location.search)
    if (dataIndex === 'status') {
      return {
        filterIcon: (<Icon type='filter' theme='outlined' />),
        filterDropdown: (

          <div className='isoTableSearchBox' style={{ display: 'flex', flexDirection: 'column', width: '200px' }}>
            <select
              id={'status'}
              onChange={e => this.onInputChange(e, dataIndex)}
              value={isChange ? searchTextQuery[dataIndex] : querySearch[dataIndex] !== undefined ? querySearch[dataIndex] : searchTextQuery[dataIndex]}
            >
              <option key='Unresolved' value='Unresolved'>Unresolved</option>
              <option key='Resolved' value='Resolved'>Resolved</option>
            </select>
            <Button type='primary' onClick={e => this.onSearch(e, dataIndex)} style={{ marginTop: '10px' }}>
              Search
            </Button>
          </div>
        ),

        filterDropdownVisible: this.state[dataIndex],
        onFilterDropdownVisibleChange: visible => this.setState({ [dataIndex]: visible })
      }
    } else if (dataIndex === 'claim_number') {
      return {
        filterIcon: (<Icon type='search' />),
        filterDropdown: (
          <FilterInput
            idIdentifier={dataIndex}
            searchText={isChange ? searchTextQuery[dataIndex] : querySearch[dataIndex] !== undefined ? querySearch[dataIndex] : searchTextQuery[dataIndex]}
            onInputChange={e => this.onInputChange(e, dataIndex)}
            onSearch={e => this.onSearch(e, dataIndex, 'text')}

          />
        ),
        filterDropdownVisible: this.state[dataIndex],
        onFilterDropdownVisibleChange: visible => this.setState({ [dataIndex]: visible })
      }
    } else if (dataIndex === 'ticket_no') {
      return {
        filterIcon: (<Icon type='search' />),
        filterDropdown: (
          <FilterInput
            idIdentifier={dataIndex}
            searchText={isChange ? searchTextQuery[dataIndex] : querySearch[dataIndex] !== undefined ? querySearch[dataIndex] : searchTextQuery[dataIndex]}
            onInputChange={e => this.onInputChange(e, dataIndex)}
            onSearch={e => this.onSearch(e, dataIndex, 'text')}
          />
        ),
        filterDropdownVisible: this.state[dataIndex],
        onFilterDropdownVisibleChange: visible => this.setState({ [dataIndex]: visible })
      }
    } else if (dataIndex === 'partnerproduct_id') {
      const options = products.map((d) => <Option key={d.id}>{d.display_name}</Option>)
      return {
        filterIcon: (<Icon type='filter' theme='outlined' />),
        filterDropdown: (
          <div className='isoTableSearchBox' style={{ display: 'flex', flexDirection: 'column', width: '200px' }}>
            <Select
              showSearch
              placeholder='Select Product'
              id={'partnerproduct_id'}
              onChange={e => this.onSelectProduct(e, dataIndex)}
              onSearch={e => this.onSearch(e, dataIndex, 'text')}
              value={isChange ? searchTextQuery[dataIndex] : querySearch[dataIndex] !== undefined ? querySearch[dataIndex] : searchTextQuery[dataIndex]}
            >
              {options}
            </Select>
            <Button type='primary' onClick={e => this.onSearch(e, dataIndex)} style={{ marginTop: '10px' }}>
              Search
            </Button>
          </div>
        ),
        filterDropdownVisible: this.state[dataIndex],
        onFilterDropdownVisibleChange: visible => this.setState({ [dataIndex]: visible })
      }
    }
  };

  onSelectProduct = (event, identifier) => {
    this.setState({
      searchTextQuery: { [identifier]: event },
      isChange: true
    })
  }
  onInputChange = (event, identifier) => {
    this.setState({
      searchTextQuery: { [identifier]: event.target.value },
      isChange: true
    })
  }

  onSearch = () => {
    let dateSearch = {}

    const { searchTextQuery } = this.state
    const { history, location } = this.props

    const finalFilter = { ...searchTextQuery, ...dateSearch }
    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({
      pathname: location.pathname,
      search: searchQuery
    })
    if (Object.values(searchTextQuery).length || Object.values(dateSearch).length) {
      this.setState({
        ticketId: false,
        claimId: false,
        searchTextQuery: finalFilter
      })
      this.fetch(finalFilter)
    }
  }
  resetFilter = () => {
    const { history, location } = this.props

    location.search = ''
    history.push(location.pathname)
    this.setState({
      searchText: '',
      loading: true,
      searchTextQuery: {},
      notificationsFilter: {},
      filteredInfo: {},
      clearDate: true
    })

    this.fetch()
  }

  handleTableChange = (pagination, filters) => {
    const { searchTextQuery, filteredInfo } = this.state
    const { history, location } = this.props
    const { pageSize, current } = pagination
    //   const offset = pageSize * (current - 1)
    const filterObj = {}
    Object.keys(filters).forEach((key) => {
      let value = (filters[key] || [])
      value = Array.isArray(value) ? value[0] : value
      if (value) filterObj[key] = value
    })

    const finalFilter = {
      ...searchTextQuery,
      ...filterObj,
      page: current,
      page_size: pageSize
    }

    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({
      pathname: location.pathname,
      search: searchQuery
    })
    this.setState({
      ticketId: false,
      claimId: false,
      onSearchQuery: finalFilter,
      searchTextQuery: finalFilter,
      filteredInfo: { ...filterObj },
      page: current,
      page_size: pageSize

    })
    this.props.listticketData({ page: current, page_size: pageSize, ...finalFilter })

    if (JSON.stringify(filterObj) === JSON.stringify(filteredInfo)) return
    this.fetch(finalFilter)
  };

  fetch = (params = {}) => {
    const { page, page_size: pageCount } = params
    const pageNumber = Number(page) || 1
    const pageSize = Number(pageCount) || 10
    delete params.page
    delete params.page_size
    this.setState({
      page_size: pageSize,
      page: pageNumber,
      loading: false,
      notificationsFilter: params
    })
    this.props.listticketData({ page: pageNumber, page_size: pageSize, ...params })
  };

  render () {
    const {
      listticketData,
      page,
      totalRecords,
      notificationsFilter
    } = this.state
    const {
      internalUsers
    } = this.props
    const listticketDataColumns = [

      {
        key: 'ticket_no',
        title: 'Ticket ID',
        dataIndex: 'ticket_no',
        render: (val, data) => {
          return (
            <span
              onClick={() => this.detailPage(data.claim_id)}
              style={{ cursor: 'pointer', color: '#2a8eeb', fontWeight: 'bold' }}
            >
              {val}
            </span>
          )
        },
        align: 'center',
        ...this.getColumnSearchProps('ticket_no')

      },
      {
        key: 'created_at',
        title: 'Date and Time',
        dataIndex: 'created_at',
        align: 'center'
      },
      {
        key: 'text',
        title: 'Notification Text',
        dataIndex: 'text',
        render: val => {
          return (
            <span>
              {val || '-'}
            </span>
          )
        },
        align: 'center'
      },
      {
        key: 'resolved_by',
        title: 'Resolved By',
        dataIndex: 'resolved_by',
        align: 'center',
        render: val => {
          if (internalUsers) {
            var name = ''
            internalUsers.forEach(item => {
              if (item.id === val) {
                name = item.name
              }
            })
            return (
              <span>{name}</span>
            )
          }
        }
      },
      {
        key: 'partnerproduct_id',
        title: 'Product Name',
        dataIndex: 'display_name',
        align: 'center',
        ...this.getColumnSearchProps('partnerproduct_id')

      },
      {
        key: 'ticket_source',
        title: 'Notification Type',
        dataIndex: 'ticket_source',
        align: 'center'
      },
      {
        key: 'claim_number',
        title: 'Claim ID',
        dataIndex: 'claim_number',
        align: 'center',
        ...this.getColumnSearchProps('claim_number')

      },
      {
        key: 'status',
        title: 'Status',
        dataIndex: 'status',
        align: 'center',
        render: val => {
          return (
            <span style={{ fontWeight: val === 'Unresolved' ? 'bold' : ' ' }}>
              {val}
            </span>
          )
        },
        ...this.getColumnSearchProps('status')

      }
    ]
    return (
      <LayoutContentWrapper
        className='referral-table'
        style={{ color: '#788195' }}
      >
        <LayoutContent>
          <Row style={{ marginBottom: '10px' }}>
            <div>
              <h3 style={{ float: 'left', color: '#788195' }}>Notifications</h3>
            </div>
            {
              Object.keys(notificationsFilter).length > 0 && (
                <Tag
                  style={{ alignSelf: 'center', marginLeft: '5px' }}
                  color='purple'>

                  Filter is applied
                </Tag>
              )
            }
            <div style={{ float: 'right', display: 'flex' }}>
              <Button onClick={this.resetFilter}>
                <Icon type='filter' theme='outlined' /> &nbsp;Clear filter
              </Button>

            </div>
          </Row>
          <Table
            // loading={this.state.loading}
            showHeader
            columns={listticketDataColumns}
            onChange={this.handleTableChange}
            dataSource={listticketData || []}
            pagination={{
              pageSize: 10,
              total: totalRecords,
              current: page
            }}
          />
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

Notifications.propTypes = {
  listticketData: PropTypes.object.isRequired
}

Notifications.defaultProps = {
  listticketData: []
}

export default connect(
  state => ({
    data: state.Claims,
    dataProfile: state.Auth.profile,
    internalUsers: state.User.internalUsers,
    internalUsersLoading: state.Loading.GET_INTERNAL_USERS,
    internalUsersError: state.Error.GET_INTERNAL_USERS,
    products: state.Insurance.products
  }),
  {
    listticketData,
    getInternalUsers,
    getProducts
  }
)(Notifications)
